// ===== 检查登录状态 =====
function checkLogin(){
	try{
		var co = String(cookie.getCookie("https://lucifer-club.com"));
		if(co.indexOf("lnfo") < 0){
			java.longToast("❌ 未登录：请先点「👤 登录/重新登录」");
			return;
		}
		var m = co.match(/lnfo=([^;]+)/);
		var name = "";
		if(m){
			try{
				var s = java.base64Decode(decodeURIComponent(m[1]));
				var um = String(s).match(/s:\d+:"([^"]+)"/);
				name = um ? um[1] : "";
			}catch(e){}
		}
		if(name){
			java.longToast("✅ 已登录，当前账号：「" + name + "」");
		}else{
			java.longToast("✅ 已登录（Cookie有效）");
		}
	}catch(e){
		java.toast("检查登录状态失败：" + e);
	}
}

