@js:function fmt(h){
	var s=String(h||'');
	s=s.replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/p>/gi,'\n').replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"');
	s=s.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').replace(/^\s+|\s+$/g,'');
	return s;
}
var quotes=String(src).match(/<li class="luf_book_quote">[\s\S]*?<\/li>/g)||[];
var cont='';
if(quotes.length){
	cont+='📖【作品简介】\n'+fmt(quotes[0]);
	if(quotes.length>1&&fmt(quotes[1]).length>0){
		cont+='\n📝【絮言絮语】\n'+fmt(quotes[1]);
	}
}
function cleanT(h){return String(h).replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();}
function cleanC(h){return String(h).replace(/<[^>]+>/g,'').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();}
function parseC(html,arr,cap){
	var blks=String(html).match(/<ul class="luf_comment">[\s\S]*?<\/ul>/g)||[];
	for(var i=0;i<blks.length&&arr.length<cap;i++){
		var b=blks[i];
		var tm=b.match(/<li class="luf_comment_title">([\s\S]*?)<\/li>/);
		var cm=b.match(/<li class="luf_comment_contents">([\s\S]*?)<\/li>/);
		if(!tm||!cm)continue;
		var t=cleanT(tm[1]).replace(/《\s+/g,'《').replace(/\s+》/g,'》').replace(/\s+说/g,'说');
		var c=cleanC(cm[1]);
		if(t&&c)arr.push({'t':t,'c':c});
	}
}
function maxPage(html){
	var pg=String(html).match(/<div class="pages">([\s\S]*?)<\/div>/);
	if(!pg)return 1;
	var ns=pg[1].match(/page=(\d+)/g)||[];
	var mx=1;
	for(var i=0;i<ns.length;i++){var n=Number((String(ns[i]).match(/\d+/)||[])[0]||1);if(n>mx)mx=n;}
	return mx;
}
